part_b.solution:
#include <stdio.h>

int main() {
    int r1, c1, r2, c2;
    printf("Enter rows and cols for Matrix A: ");
    scanf("%d %d", &r1, &c1);
    printf("Enter rows and cols for Matrix B: ");
    scanf("%d %d", &r2, &c2);

    if (c1 != r2) {
        printf("Error: Multiplication not possible! Col1 (%d) != Row2 (%d)\n", c1, r2);
        return 1;
    }

    int A[r1][c1], B[r2][c2], C[r1][c2];
    printf("Enter elements of Matrix A:\n");
    for(int i=0; i<r1; i++)
        for(int j=0; j<c1; j++)
            scanf("%d", &A[i][j]);

    printf("Enter elements of Matrix B:\n");
    for(int i=0; i<r2; i++)
        for(int j=0; j<c2; j++)
            scanf("%d", &B[i][j]);

    for(int i=0; i<r1; i++) {
        for(int j=0; j<c2; j++) {
            C[i][j] = 0;
            for(int k=0; k<c1; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    printf("Resultant Matrix C (%d x %d):\n", r1, c2);
    for(int i=0; i<r1; i++) {
        for(int j=0; j<c2; j++)
            printf("%d\t", C[i][j]);
        printf("\n");
    }
    return 0;
}

1. malloc(size_t size):
Allocates a contiguous block of specified bytes in the heap memory. Memory is uninitialized (contains garbage values).
Syntax: ptr = (cast_type*) malloc(byte_size);

2. calloc(size_t n, size_t size):
Allocates memory for an array of n elements, each of size bytes. Initializes all allocated bits to zero.
Syntax: ptr = (cast_type*) calloc(n, element_size);

3. realloc(void *ptr, size_t new_size):
Resizes an existing dynamically allocated memory block pointed to by ptr. May move the block if adjacent memory is unavailable.
Syntax: ptr = (cast_type*) realloc(ptr, new_size);

4. free(void *ptr):
Deallocates dynamically allocated memory block back to the heap pool to prevent memory leaks.
Syntax: free(ptr); ptr = NULL;

#include <stdio.h>

struct Student {
    int roll_no;
    char name[50];
    float marks[3];
    float total;
    char grade;
};

char calculateGrade(float total) {
    float pct = total / 3.0;
    if (pct >= 90) return 'O';
    if (pct >= 75) return 'A';
    if (pct >= 60) return 'B';
    return 'C';
}

int main() {
    struct Student s[5];
    FILE *fp = fopen("students.dat", "wb");
    if (!fp) {
        printf("File open failed!\n");
        return 1;
    }
    for(int i=0; i<5; i++) {
        printf("Enter Roll No and Name: ");
        scanf("%d %s", &s[i].roll_no, s[i].name);
        s[i].total = 0;
        printf("Enter marks for 3 subjects: ");
        for(int j=0; j<3; j++) {
            scanf("%f", &s[i].marks[j]);
            s[i].total += s[i].marks[j];
        }
        s[i].grade = calculateGrade(s[i].total);
    }
    fwrite(s, sizeof(struct Student), 5, fp);
    fclose(fp);
    printf("Successfully written 5 student records to students.dat!\n");
    return 0;
}

