class BankAccount:
    def __init__(self, acc_no, holder, balance=0.0):
        self._acc_no = acc_no
        self._holder = holder
        self._balance = balance
        self._history = []

    def deposit(self, amount):
        if amount > 0:
            self._balance += amount
            self._history.append(f'Deposit: +{amount}')
            return True
        return False

    def withdraw(self, amount):
        if 0 < amount <= self._balance:
            self._balance -= amount
            self._history.append(f'Withdraw: -{amount}')
            return True
        return False

class SavingsAccount(BankAccount):
    def __init__(self, acc_no, holder, balance=0.0, interest_rate=0.04):
        super().__init__(acc_no, holder, balance)
        self.interest_rate = interest_rate

    def apply_interest(self):
        interest = self._balance * self.interest_rate
        self.deposit(interest)
        self._history.append(f'Interest added: +{interest}')

class CurrentAccount(BankAccount):
    def __init__(self, acc_no, holder, balance=0.0, overdraft_limit=10000.0):
        super().__init__(acc_no, holder, balance)
        self.overdraft_limit = overdraft_limit

    def withdraw(self, amount):
        if 0 < amount <= (self._balance + self.overdraft_limit):
            self._balance -= amount
            self._history.append(f'Current Withdraw: -{amount} (Bal: {self._balance})')
            return True
        return False
